    "chapterId": "a0548",
    "chapterNumber": 137,
    "sortOrder": 137,
    "chapterTitle": "卷4 · 将革命进行到底",
    "group": "战略与战争",
    "title": "将革命进行到底｜伴读",
    "variant": "伴读",
